#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(AP_CTX_IN.len(), 37);
    assert_eq!(AP_CTX_OUT.len(), AP_CTX_IN.len());
    assert_eq!(AP_FRAMES_IN.len(), 24);
    assert_eq!(AP_FRAMES_OUT.len(), AP_FRAMES_IN.len());
    assert!(AP_FRAMES_IN != AP_FRAMES_OUT);
}
